{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise TypeError("case must be an object")
    required = ("segments", "budget")
    for key in required:
        if key not in case:
            raise ValueError("missing required field: " + key)
    segments = case["segments"]
    budget = case["budget"]
    if not isinstance(segments, list):
        raise TypeError("segments must be a list")
    if isinstance(budget, bool) or not isinstance(budget, int):
        raise TypeError("budget must be an integer")
    parsed = []
    for segment in segments:
        if not isinstance(segment, dict):
            raise TypeError("each segment must be an object")
        for key in ("name", "importance", "minimum", "capacity"):
            if key not in segment:
                raise ValueError("missing required segment field: " + key)
        name = segment["name"]
        importance = segment["importance"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]
        if not isinstance(name, str):
            raise TypeError("segment name must be a string")
        for value, label in ((importance, "importance"), (minimum, "minimum"), (capacity, "capacity")):
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError("segment " + label + " must be an integer")
        if minimum < 0 or capacity < minimum:
            raise ValueError("invalid segment quota or capacity")
        parsed.append((name, importance, minimum, capacity))
    quota = sum(item[2] for item in parsed)
    capacity_total = sum(item[3] for item in parsed)
    if budget < quota or budget > capacity_total:
        raise ValueError("budget outside feasible range")
    allocations = [item[2] for item in parsed]
    remaining = budget - quota
    while remaining:
        best = None
        for index, item in enumerate(parsed):
            if allocations[index] >= item[3]:
                continue
            importance = item[1]
            position = allocations[index] + 1
            if best is None or importance * best[1] > best[0] * position:
                best = (importance, position, index)
        if best is None:
            raise ValueError("budget cannot be allocated")
        allocations[best[2]] += 1
        remaining -= 1
    return {"allocations": allocations, "by_name": {item[0]: allocations[index] for index, item in enumerate(parsed)}, "total": sum(allocations)}"}
